From cd7306485e7041fbcc0272fd4d2559d667903900 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 08:59:55 +0100
Subject: [PATCH] wayland: Re-read a surface's shadow when its contents are
 committed

The shadow is set on the surface at creation time, so a wl_surface commit
arriving before org_kde_kwin_shadow.commit applies an empty shadow that is
never re-read. Mark the shadow as changed so the next commit picks it up.

BUG: 516030
---
 src/wayland/shadow_interface.cpp | 7 +++++++
 1 file changed, 7 insertions(+)

diff --git a/src/wayland/shadow_interface.cpp b/src/wayland/shadow_interface.cpp
index c775fa1e69..a1c0835556 100644
--- a/src/wayland/shadow_interface.cpp
+++ b/src/wayland/shadow_interface.cpp
@@ -175,6 +175,13 @@ void ShadowInterfacePrivate::org_kde_kwin_shadow_commit(Resource *resource)
         offset = pending.offset;
     }
     pending = Commit();
+
+    if (surface) {
+        SurfaceInterfacePrivate *surfacePrivate = SurfaceInterfacePrivate::get(surface);
+        if (!(surfacePrivate->pending->committed & SurfaceState::Field::Shadow) && surfacePrivate->current->shadow == q) {
+            surfacePrivate->setShadow(QPointer<ShadowInterface>(q));
+        }
+    }
 }

 void ShadowInterfacePrivate::attach(Commit::Flags flag, wl_resource *buffer)
